const categoryMeta = {
  museum:{label:{es:'MUSEO',en:'MUSEUM',pt:'MUSEU',fr:'MUSÉE'},color:'#ff514b'}, coffee:{label:{es:'CAFETERÍA',en:'COFFEE',pt:'CAFETERIA',fr:'CAFÉ'},color:'#9b5d2d'}, food:{label:{es:'COMIDA CHILENA',en:'CHILEAN FOOD',pt:'COMIDA CHILENA',fr:'CUISINE CHILIENNE'},color:'#e26b1f'}, view:{label:{es:'PASEO Y VISTA',en:'WALK & VIEW',pt:'PASSEIO E VISTA',fr:'BALADE ET VUE'},color:'#168c74'}, stay:{label:{es:'HOTEL',en:'HOTEL',pt:'HOTEL',fr:'HÔTEL'},color:'#7c55c7'}, useful:{label:{es:'ÚTIL',en:'USEFUL',pt:'ÚTIL',fr:'PRATIQUE'},color:'#2468b4'}
};

let locale = localStorage.getItem('sos-language') || 'es'; let currentCategory = 'all';
const map = L.map('map',{zoomControl:false,scrollWheelZoom:false}).setView([-33.4489,-70.6693],12); L.control.zoom({position:'bottomleft'}).addTo(map); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);
const routeLine = L.polyline(routeStops.map(stop=>stop.coords),{color:'#ff514b',weight:4,opacity:.9,dashArray:'3 9'}).addTo(map);
const markers = routeStops.map((stop,index)=>{const icon=L.divIcon({className:'',html:`<div style="width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:${index===0?'#ff514b':'#081a36'};color:white;border:3px solid white;box-shadow:0 5px 16px #081a3655;font:800 15px DM Sans">${index+1}</div>`,iconSize:[34,34],iconAnchor:[17,17]});return L.marker(stop.coords,{icon}).addTo(map).bindPopup(`<b>${index+1}. ${stop.name}</b>`);}); map.fitBounds(routeLine.getBounds(),{padding:[42,42]});
function focusStop(index){map.flyTo(routeStops[index].coords,index===0?13:15,{duration:.8});markers[index].openPopup();document.querySelectorAll('.stop-card').forEach((card,i)=>card.classList.toggle('active',i===index));}
document.querySelectorAll('.stop-card').forEach(card=>{const handler=()=>focusStop(Number(card.dataset.stop));card.addEventListener('click',handler);card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();handler();}});});
document.getElementById('fit-route-button').addEventListener('click',()=>{document.getElementById('map').scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>map.fitBounds(routeLine.getBounds(),{padding:[42,42]}),350);}); document.getElementById('all-stops-button').addEventListener('click',()=>map.fitBounds(routeLine.getBounds(),{padding:[42,42]}));

const placesMap=L.map('places-map',{zoomControl:false,scrollWheelZoom:false}).setView([-33.435,-70.650],12); L.control.zoom({position:'bottomleft'}).addTo(placesMap); L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(placesMap); let placeMarkers=[];
function mapsUrl(place){return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(place.name+' Santiago Chile')}`;} function ratingLabel(place){return place.rating.match(/^\d/)?`★ ${place.rating}${place.reviews&&place.reviews!=='—'?` · ${place.reviews}`:''}`:place.rating;}
function renderPlaces(){const shown=places.filter(place=>currentCategory==='all'||place.category===currentCategory);document.getElementById('visible-count').textContent=shown.length;document.getElementById('place-list').innerHTML=shown.map(place=>`<article class="place-card" tabindex="0" data-place="${place.id}"><div class="place-card-top"><span class="place-category">${categoryMeta[place.category].label[locale]}</span><span class="place-rating">${ratingLabel(place)}</span></div><h3>${place.name}</h3><p>${place.summary[locale]}</p><a href="${mapsUrl(place)}" target="_blank" rel="noreferrer">Google Maps ↗</a></article>`).join('');placeMarkers.forEach(marker=>placesMap.removeLayer(marker));placeMarkers=[];shown.forEach(place=>{const color=categoryMeta[place.category].color;const icon=L.divIcon({className:'',html:`<div style="width:28px;height:28px;border-radius:9px 9px 9px 2px;transform:rotate(-45deg);background:${color};border:2px solid white;box-shadow:0 4px 12px #081a3644"><span style="display:grid;place-items:center;transform:rotate(45deg);width:100%;height:100%;color:white;font-size:11px">●</span></div>`,iconSize:[28,28],iconAnchor:[14,14]});placeMarkers.push(L.marker(place.coords,{icon}).addTo(placesMap).bindPopup(`<b>${place.name}</b><br><span>${place.summary[locale]}</span><br><a href="${mapsUrl(place)}" target="_blank" rel="noreferrer">Google Maps ↗</a>`));});if(shown.length)placesMap.fitBounds(L.latLngBounds(shown.map(p=>p.coords)),{padding:[35,35],maxZoom:14});document.querySelectorAll('.place-card').forEach(card=>{const handler=()=>{const place=places.find(p=>p.id===card.dataset.place);const index=shown.findIndex(p=>p.id===place.id);placesMap.flyTo(place.coords,15,{duration:.7});placeMarkers[index].openPopup();};card.addEventListener('click',e=>{if(e.target.tagName!=='A')handler();});card.addEventListener('keydown',e=>{if(e.key==='Enter')handler();});});}
document.querySelectorAll('.place-filter').forEach(button=>button.addEventListener('click',()=>{currentCategory=button.dataset.category;document.querySelectorAll('.place-filter').forEach(b=>b.classList.toggle('active',b===button));renderPlaces();}));
function applyLanguage(lang){locale=lang;localStorage.setItem('sos-language',lang);document.documentElement.lang=lang;document.getElementById('language-select').value=lang;document.querySelectorAll('[data-i18n]').forEach(el=>{const value=translations[lang][el.dataset.i18n];if(value!==undefined)el.innerHTML=value;});renderPlaces();} document.getElementById('language-select').addEventListener('change',e=>applyLanguage(e.target.value));
document.getElementById('locate-button').addEventListener('click',()=>{const status=document.getElementById('location-status');const msg={es:{search:'Buscando tu ubicación…',fail:'No pudimos acceder a tu ubicación. Revisa el permiso del navegador.',found:'Tu lugar útil más cercano es'},en:{search:'Finding your location…',fail:'We could not access your location. Check browser permission.',found:'Your nearest useful place is'},pt:{search:'Buscando sua localização…',fail:'Não foi possível acessar sua localização. Verifique a permissão.',found:'O lugar útil mais próximo é'},fr:{search:'Recherche de votre position…',fail:'Impossible d’accéder à votre position. Vérifiez l’autorisation.',found:'Le lieu utile le plus proche est'}}[locale];if(!navigator.geolocation){status.textContent=msg.fail;return;}status.textContent=msg.search;navigator.geolocation.getCurrentPosition(position=>{const here=[position.coords.latitude,position.coords.longitude];const nearest=places.reduce((best,p)=>{const d=Math.hypot(p.coords[0]-here[0],p.coords[1]-here[1]);return !best||d<best.d?{p,d}:best;},null).p;L.circleMarker(here,{radius:8,color:'#081a36',fillColor:'#ffd21f',fillOpacity:1,weight:4}).addTo(placesMap).bindPopup('●').openPopup();placesMap.fitBounds(L.latLngBounds([here,nearest.coords]),{padding:[55,55],maxZoom:14});status.textContent=`${msg.found}: ${nearest.name}.`;document.getElementById('places-map').scrollIntoView({behavior:'smooth',block:'center'});},()=>{status.textContent=msg.fail;},{enableHighAccuracy:true,timeout:10000});});
applyLanguage(locale);
